# T-0001 Implementation Brief: Set up HTML canvas and game structure

## Target File
`index.html` — single file, no external dependencies

## Implementation Plan

### Step 1: HTML skeleton
Create `index.html` with:
- DOCTYPE, head with meta charset/viewport, title "Snake Game"
- Embedded `<style>` block (see CSS below)
- Body containing a `<div class="container">` with:
  - `<div class="hud">`: two spans — `<span id="score">Score: 0</span>` and `<span id="best">Best: 0</span>`
  - `<canvas id="game" width="400" height="400"></canvas>`
  - `<div id="overlay" class="overlay hidden">`: contains `<h2>Game Over</h2>`, `<p id="final-score"></p>`, `<button id="restart-btn">Play Again</button>`
- Embedded `<script>` block at end of body

### Step 2: CSS (embedded)
```css
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #1a1a2e; color: #e0e0e0; font-family: 'Segoe UI', sans-serif; display: flex; justify-content: center; align-items: center; min-height: 100vh; }
.container { text-align: center; }
.hud { display: flex; justify-content: space-between; padding: 8px 4px; font-size: 16px; max-width: 400px; margin: 0 auto 8px; }
.hud #score { color: #00ff88; font-weight: bold; }
.hud #best { color: #888; }
canvas { border: 2px solid #333; border-radius: 4px; display: block; margin: 0 auto; background: #16213e; }
.overlay { position: absolute; top: 0; left: 0; width: 400px; height: 400px; background: rgba(0,0,0,0.85); display: flex; flex-direction: column; justify-content: center; align-items: center; border-radius: 4px; }
.overlay.hidden { display: none; }
.overlay h2 { color: #ff6b6b; font-size: 28px; margin-bottom: 12px; }
.overlay p { color: #e0e0e0; font-size: 18px; margin-bottom: 20px; }
.overlay button { background: #00ff88; color: #1a1a2e; border: none; padding: 10px 28px; font-size: 16px; border-radius: 6px; cursor: pointer; font-weight: bold; }
.overlay button:hover { background: #00cc6a; }
.canvas-wrap { position: relative; display: inline-block; }
```

### Step 3: JavaScript — Config & State
```javascript
const CONFIG = { GRID_SIZE: 20, CELL_SIZE: 20, INITIAL_SPEED: 150, SPEED_INCREMENT: 2, MIN_SPEED: 60 };
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
let state = {
  snake: [{x:10,y:10}], direction: {x:1,y:0}, nextDirection: {x:1,y:0},
  food: {x:15,y:10}, score: 0, bestScore: 0, gameOver: false,
  speed: CONFIG.INITIAL_SPEED, intervalId: null
};
```

### Step 4: JavaScript — Render function
```javascript
function render() {
  ctx.fillStyle = '#16213e';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // Draw grid lines
  ctx.strokeStyle = 'rgba(255,255,255,0.03)';
  for (let i = 0; i <= CONFIG.GRID_SIZE; i++) {
    ctx.beginPath(); ctx.moveTo(i*CONFIG.CELL_SIZE, 0); ctx.lineTo(i*CONFIG.CELL_SIZE, canvas.height); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i*CONFIG.CELL_SIZE); ctx.lineTo(canvas.width, i*CONFIG.CELL_SIZE); ctx.stroke();
  }
  // Draw food
  const fx = state.food.x * CONFIG.CELL_SIZE + CONFIG.CELL_SIZE/2;
  const fy = state.food.y * CONFIG.CELL_SIZE + CONFIG.CELL_SIZE/2;
  ctx.fillStyle = '#ff6b6b';
  ctx.beginPath(); ctx.arc(fx, fy, CONFIG.CELL_SIZE/2 - 2, 0, Math.PI*2); ctx.fill();
  // Draw snake
  state.snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#00ff99' : '#00ff88';
    ctx.fillRect(seg.x*CONFIG.CELL_SIZE+1, seg.y*CONFIG.CELL_SIZE+1, CONFIG.CELL_SIZE-2, CONFIG.CELL_SIZE-2);
  });
  // Update HUD
  document.getElementById('score').textContent = 'Score: ' + state.score;
  document.getElementById('best').textContent = 'Best: ' + state.bestScore;
}
```

### Step 5: JavaScript — Init, spawnFood, startLoop
```javascript
function spawnFood() {
  let pos;
  do { pos = { x: Math.floor(Math.random()*CONFIG.GRID_SIZE), y: Math.floor(Math.random()*CONFIG.GRID_SIZE) };
  } while (state.snake.some(s => s.x === pos.x && s.y === pos.y));
  return pos;
}
function startLoop() {
  if (state.intervalId) clearInterval(state.intervalId);
  state.intervalId = setInterval(tick, state.speed);
}
function tick() { /* stub — implemented in T-0002 */ render(); }
function init() {
  state.snake = [{x:10,y:10}]; state.direction = {x:1,y:0}; state.nextDirection = {x:1,y:0};
  state.score = 0; state.gameOver = false; state.speed = CONFIG.INITIAL_SPEED;
  try { state.bestScore = parseInt(localStorage.getItem('snakeBest')) || 0; } catch(e) {}
  state.food = spawnFood();
  document.getElementById('overlay').classList.add('hidden');
  render(); startLoop();
}
document.getElementById('restart-btn').addEventListener('click', init);
init();
```

## Wrap the canvas and overlay
The overlay must be positioned absolutely over the canvas inside `.canvas-wrap`.

## Testing
- Open index.html in browser — should show dark canvas with green square at (10,10) and red circle food
- Score HUD visible: "Score: 0" / "Best: 0"
- No console errors
- Game loop is ticking (render called repeatedly)
